$base='/home/hddrecov/public_html/forum';
$targets=array(
  $base.'/vbdlmanager/_bootstrap_fix19m.php',
);
$out=array('ok'=>true,'ts'=>time(),'rev'=>'rmboot19m','deleted'=>array());
foreach($targets as $p){
  if(is_file($p)){
    @chmod($p,0666);
    $out['deleted'][$p]=@unlink($p)?1:0;
  } else {
    $out['deleted'][$p]='absent';
  }
}
@file_put_contents($base.'/vbdlmanager/_deploy_rmboot19m.json', json_encode($out));
return true;
